sys_script_include.script:
var PatientUtilsClient = Class.create();
PatientUtilsClient.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getPatientDetails: function() {
        var patientId = this.getParameter('sysparm_patient_id');

        var gr = new GlideRecord('u_patient_record');
        if (gr.get(patientId)) {
            var data = {
                first_name: gr.getValue('u_first_name'),
                last_name: gr.getValue('u_last_name'),
                gender: gr.getValue('u_gender'),
            };
            return JSON.stringify(data);
        }

        return '';
    }

});
